import pathlib,sys,json,itertools,collections,importlib.util,time
import numpy as np,sympy as sp,networkx as nx
R=pathlib.Path(r'C:\Repos\Theory of Everything');sys.path.insert(0,str(R/'analysis'))
sys.stdout.reconfigure(encoding='utf-8',errors='replace')
def inv5(A):return np.array(sp.Matrix(A.tolist()).inv_mod(5)).astype(np.int64)%5
def gf2(A,b):
 a=np.column_stack([A,b]).astype(np.uint8);row=0;piv=[]
 for c in range(A.shape[1]):
  found=np.flatnonzero(a[row:,c])
  if not len(found):continue
  k=row+found[0];a[[row,k]]=a[[k,row]]
  for j in range(len(a)):
   if j!=row and a[j,c]:a[j]^=a[row]
  piv.append(c);row+=1
 if any(not z[:-1].any() and z[-1] for z in a):return None
 x=np.zeros(A.shape[1],dtype=np.uint8)
 for j,c in enumerate(piv):x[c]=a[j,-1]
 return x
def cubic_probe():
 import w33_20261031_continuum_chirality as old
 g=json.loads((R/'data/w33_20261031_petersen_stabilizer.json').read_text())
 d=old.internal_e6_support(g['signed_five_dimensional_generators']);tri=[tuple(t)for t in d['cubic_support']]
 native=json.loads((R/'artifacts/canonical_su3_gauge_and_cubic.json').read_text())['solution']['d_triples']
 nt={tuple(sorted(t['triple'])):int(t['sign']) for t in native}
 def graph(ts,anchor):
  H=nx.Graph();H.add_nodes_from(range(27));H.add_edges_from((a,b)for t in ts for a,b in itertools.combinations(t,2))
  nx.set_node_attributes(H,{i:0 if i==anchor else 1 if H.has_edge(i,anchor) else 2 for i in H},'sector');return H
 W=graph(tri,0);N=graph(nt,0)
 match=next(nx.isomorphism.GraphMatcher(W,N,node_match=lambda a,b:a['sector']==b['sector']).isomorphisms_iter())
 coeff={t:nt[tuple(sorted(match[i]for i in t))]for t in tri}
 A=np.zeros((46,27),dtype=int)
 for i,t in enumerate(tri):A[i,list(t)]=1
 A[-1,0]=1
 signed=[]
 for perm in d['generator_permutations']:
  b=np.array([int(coeff[t]!=coeff[tuple(sorted(perm[i]for i in t))]) for t in tri]+[0])
  bits=gf2(A,b);assert bits is not None
  signed.append((tuple(perm),tuple(map(int,bits))))
 ident=(tuple(range(27)),(0,)*27);seen={ident};queue=[ident]
 def mul(g,h):
  p,s=g;q,t=h;return tuple(p[q[i]]for i in range(27)),tuple(t[i]^s[q[i]]for i in range(27))
 for x in queue:
  for g0 in signed:
   y=mul(g0,x)
   if y not in seen:seen.add(y);queue.append(y)
  if len(seen)>100000:raise RuntimeError('unexpected order')
 print('SIGNED_CUBIC',len(seen),'kernel',sum(p==ident[0]for p,s in seen),flush=True)
 out=dict(weight_to_native=[match[i]for i in range(27)],coefficient_rows=[dict(triple=t,coefficient=coeff[t])for t in tri],signed_generators=[dict(permutation=p,sign_bits=s)for p,s in signed],order=len(seen),kernel_order=sum(p==ident[0]for p,s in seen))
 (R/'data/w33_20261031_signed_cubic_probe.json').write_text(json.dumps(out,indent=2))
 return out
def unitary_probe():
 g=json.loads((R/'data/w33_20261031_petersen_stabilizer.json').read_text());S=np.array(g['two_qubit_kernel_intertwiner']['intertwiner_mod5']);Si=inv5(S)
 X=sp.Matrix([[0,1],[1,0]]);Z=sp.diag(1,-1);I=sp.eye(2);ii=sp.I
 ts=[ii*sp.kronecker_product(X,I),ii*sp.kronecker_product(Z,I),sp.kronecker_product(I,X),sp.kronecker_product(I,Z)]
 reduce=lambda M:np.array([int(sp.re(x))+2*int(sp.im(x))for x in M]).reshape(4,4)%5
 key=lambda M:tuple(M)
 pool={key(sp.eye(4)):sp.eye(4)};queue=[sp.eye(4)]
 for a in queue:
  for t in ts:
   b=t*a
   if key(b)not in pool:pool[key(b)]=b;queue.append(b)
 bymod={tuple(reduce(M).flat):M for M in queue};assert len(bymod)==32
 lifts=[]
 for gg in g['symplectic_matrix_generators']:
  G=Si@np.array(gg)@S%5;Gi=inv5(G)
  images=[bymod[tuple((G@reduce(T)@Gi%5).flat)] for T in ts]
  rows=[]
  for A,B in zip(ts,images):
   # U A = B U, row-major vectorization.
   for r,c in itertools.product(range(4),repeat=2):
    row=[0]*16
    for k in range(4):row[r*4+k]+=A[k,c];row[k*4+c]-=B[r,k]
    rows.append(row)
  ns=sp.Matrix(rows).nullspace();assert len(ns)==1
  U=sp.Matrix(4,4,ns[0]);scale=(U.conjugate().T*U)[0,0];U=sp.simplify(U/sp.sqrt(scale))
  assert U.conjugate().T*U==sp.eye(4)
  def rat5(x):
   a,b=sp.fraction(x);return int(a)*pow(int(b),-1,5)%5
  red=lambda M:np.array([rat5(sp.re(x))+2*rat5(sp.im(x))for x in M]).reshape(4,4)%5
  U=next(phase*U for phase in [1,-1,ii,-ii]if np.array_equal(red(phase*U),G))
  lifts.append(U);print('LIFT',len(lifts),'det',sp.simplify(U.det()),'denoms',sorted({str(x)for x in U}),flush=True)
 mats=[np.array(M,dtype=complex)for M in lifts]
 def numeric_key(M):return tuple(np.rint(np.stack([M.real,M.imag],axis=-1)*2).astype(int).flat)
 seen={numeric_key(np.eye(4)):np.eye(4,dtype=complex)};queue=[np.eye(4,dtype=complex)]
 for a in queue:
  for U in mats:
   b=U@a;k=numeric_key(b)
   assert np.max(abs(np.stack([b.real,b.imag],axis=-1)*2-np.rint(np.stack([b.real,b.imag],axis=-1)*2)))<1e-10
   if k not in seen:seen[k]=b;queue.append(b)
  if len(seen)>10000:raise RuntimeError('unexpected order')
 print('UNITARY_ORDER',len(seen),flush=True)
 out=dict(order=len(seen),generators=[[[str(x)for x in row]for row in M.tolist()]for M in lifts])
 (R/'data/w33_20261031_unitary_probe.json').write_text(json.dumps(out,indent=2));return out
if __name__=='__main__':
 if sys.argv[-1]=='cubic':cubic_probe()
 else:unitary_probe()
